from __future__ import annotations

from typing import Callable

Schedule = Callable[[int], set[int]]

def archive(schedule: Schedule, deadline: int) -> set[int]:
    result: set[int] = set()
    for stage in range(deadline + 1):
        result.update(schedule(stage))
    return result

def missing_certificate(items: set[int]) -> int:
    witness = sum(x + 1 for x in items)
    assert witness not in items
    return witness

def unit_schedule(stage: int) -> set[int]:
    return {stage}

for deadline in (5, 10, 20):
    items = archive(unit_schedule, deadline)
    print(deadline, len(items), missing_certificate(items))

from __future__ import annotations

def physical_cap_table(cap: int, deadlines: list[int]) -> list[tuple[int, int]]:
    if cap < 0 or any(n < 0 for n in deadlines):
        raise ValueError("Inputs must be natural numbers")
    return [(n, (n + 1) * cap) for n in deadlines]

def growth_table(last_stage: int) -> list[tuple[int, int, int]]:
    return [(n, 2**n, 2 ** (2**n)) for n in range(last_stage + 1)]

print("Physical-cap bounds:", physical_cap_table(10**6, [0, 10, 100]))
for row in growth_table(6):
    print(row)

